import { createElement, useId, useMemo, type ReactNode } from 'react';
import { cn } from '../../utils/cn';
import { useI18n } from '../../i18n/I18nProvider';
import { LiveAnnouncer, useAnnounce, useHasLiveAnnouncer } from '../live-announcer';
import { kanbanBoardVariants, type KanbanBoardVariantProps } from './kanban-board.variants';
import { useSortable, type SortableContainer, type SortableDrag } from './useSortable';

/** The default card shape. Extend it with your own fields and pass `renderCard`. */
export interface KanbanCard {
  id: string;
  title: string;
  description?: string;
  /** Small line under the card (assignee, due date, labels…). Keep it non-interactive. */
  meta?: ReactNode;
}

export interface KanbanColumn<T extends KanbanCard = KanbanCard> {
  id: string;
  title: string;
  cards: T[];
}

/** A committed move. `toIndex` is the index in the destination column once the card left its origin. */
export interface KanbanMove {
  cardId: string;
  fromColumnId: string;
  fromIndex: number;
  toColumnId: string;
  toIndex: number;
}

export interface KanbanBoardProps<T extends KanbanCard = KanbanCard> extends KanbanBoardVariantProps {
  /** Controlled columns and cards. Apply `onMove` to them (see `moveKanbanCard`). */
  columns: KanbanColumn<T>[];
  /** Called on drop when a card lands somewhere new (pointer or keyboard). */
  onMove: (move: KanbanMove) => void;
  /** Card body. Default: title, description and meta. Must not contain interactive elements. */
  renderCard?: (card: T, state: { dragging: boolean }) => ReactNode;
  /** Plain-text name of a card for announcements. Default: `title`. */
  getCardLabel?: (card: T) => string;
  /** Click or Enter on a card (when not moving it), e.g. to open its details. */
  onCardOpen?: (card: T) => void;
  /** Accessible name of the board. Default "Board". */
  label?: string;
  /** Level of the column headings. Default 3. */
  headingLevel?: 2 | 3 | 4 | 5 | 6;
  /** Text in an empty column. Default "No cards". */
  emptyText?: ReactNode;
  disabled?: boolean;
  className?: string;
}

/** Applies a KanbanMove to the columns (immutably). Use it in your `onMove` handler. */
export function moveKanbanCard<T extends KanbanCard>(columns: KanbanColumn<T>[], move: KanbanMove): KanbanColumn<T>[] {
  const card = columns.find((c) => c.id === move.fromColumnId)?.cards.find((c) => c.id === move.cardId);
  if (!card) return columns;
  const without = columns.map((c) => (c.id === move.fromColumnId ? { ...c, cards: c.cards.filter((x) => x.id !== move.cardId) } : c));
  return without.map((c) => {
    if (c.id !== move.toColumnId) return c;
    const cards = [...c.cards];
    cards.splice(Math.min(Math.max(move.toIndex, 0), cards.length), 0, card);
    return { ...c, cards };
  });
}

const s = kanbanBoardVariants;

function DefaultCard({ card, slots }: { card: KanbanCard; slots: ReturnType<typeof kanbanBoardVariants> }) {
  return (
    <>
      <span className={cn('block', slots.cardTitle())}>{card.title}</span>
      {card.description && <span className={cn('block', slots.cardDescription())}>{card.description}</span>}
      {card.meta != null && <span className={slots.cardMeta()}>{card.meta}</span>}
    </>
  );
}

function Board<T extends KanbanCard>({
  columns,
  onMove,
  renderCard,
  getCardLabel = (card) => card.title,
  onCardOpen,
  label,
  headingLevel = 3,
  emptyText,
  disabled = false,
  size,
  className,
}: KanbanBoardProps<T>) {
  const { t } = useI18n();
  const announce = useAnnounce();
  const id = useId();
  const slots = s({ size });
  const containers = useMemo<SortableContainer[]>(() => columns.map((c) => ({ id: c.id, items: c.cards.map((card) => card.id) })), [columns]);
  const cardById = useMemo(() => new Map(columns.flatMap((c) => c.cards.map((card) => [card.id, card] as const))), [columns]);
  const columnById = useMemo(() => new Map(columns.map((c) => [c.id, c] as const)), [columns]);

  const describe = (drag: SortableDrag, key: 'kanban.pickedUp' | 'kanban.moved' | 'kanban.dropped') => {
    const card = cardById.get(drag.itemId);
    const column = columnById.get(drag.over.containerId);
    const others = column ? column.cards.filter((c) => c.id !== drag.itemId).length : 0;
    return t(key, {
      card: card ? getCardLabel(card) : drag.itemId,
      position: drag.over.index + 1,
      total: others + 1,
      column: column?.title ?? drag.over.containerId,
    });
  };

  const sortable = useSortable({
    containers,
    disabled,
    onMove: (m) => onMove({ cardId: m.itemId, fromColumnId: m.fromContainerId, fromIndex: m.fromIndex, toColumnId: m.toContainerId, toIndex: m.toIndex }),
    onDragStart: (drag) => announce(describe(drag, 'kanban.pickedUp')),
    onDragOver: (drag) => announce(describe(drag, 'kanban.moved')),
    onDragEnd: (drag) => announce(describe(drag, 'kanban.dropped')),
    onDragCancel: (drag) => {
      const card = cardById.get(drag.itemId);
      announce(t('kanban.cancelled', { card: card ? getCardLabel(card) : drag.itemId, column: columnById.get(drag.origin.containerId)?.title ?? drag.origin.containerId }));
    },
  });

  const instructionsId = `${id}-instructions`;
  return (
    <div role="group" aria-label={label ?? t('kanban.label')} className={cn(slots.root(), className)}>
      <p id={instructionsId} hidden>
        {t('kanban.instructions')}
      </p>
      {sortable.containers.map((list) => {
        const column = columnById.get(list.id);
        if (!column) return null;
        const headingId = `${id}-${list.id}`;
        const count = list.items.length;
        return (
          <section key={list.id} aria-labelledby={headingId} className={slots.column()} {...sortable.getContainerProps(list.id)}>
            <div className={slots.header()}>
              {createElement(
                `h${headingLevel}`,
                { id: headingId, className: slots.heading() },
                <span className={slots.title()}>{column.title}</span>,
                <span className={slots.count()}>
                  <span aria-hidden>{count}</span>
                  <span className="sr-only">{`, ${t('kanban.cards', { count })}`}</span>
                </span>,
              )}
            </div>
            <ul className={slots.list()}>
              {list.items.map((cardId) => {
                const card = cardById.get(cardId);
                if (!card) return null;
                const itemProps = sortable.getItemProps(cardId);
                const dragging = sortable.drag?.itemId === cardId;
                return (
                  <li key={cardId} className={slots.item()}>
                    <div
                      role="button"
                      tabIndex={disabled ? -1 : 0}
                      aria-roledescription={t('kanban.roleDescription')}
                      aria-describedby={instructionsId}
                      aria-disabled={disabled || undefined}
                      className={slots.card()}
                      {...itemProps}
                      onKeyDown={(e) => {
                        if (e.key === 'Enter' && !sortable.drag && e.target === e.currentTarget) {
                          e.preventDefault();
                          onCardOpen?.(card);
                          return;
                        }
                        itemProps.onKeyDown(e);
                      }}
                      onClick={() => onCardOpen?.(card)}
                    >
                      {renderCard ? renderCard(card, { dragging }) : <DefaultCard card={card} slots={slots} />}
                    </div>
                  </li>
                );
              })}
              {list.items.length === 0 && <li className={slots.empty()}>{emptyText ?? t('kanban.empty')}</li>}
            </ul>
          </section>
        );
      })}
    </div>
  );
}

/**
 * Kanban board: columns of cards you reorder within a column and move across columns, by
 * pointer drag or keyboard (Space picks up, arrows move, Space drops, Escape cancels). Each
 * step is announced through a LiveAnnouncer (its own, unless one is already above). Controlled:
 * render `columns`, apply `onMove`.
 */
export function KanbanBoard<T extends KanbanCard = KanbanCard>(props: KanbanBoardProps<T>) {
  const hasAnnouncer = useHasLiveAnnouncer();
  if (hasAnnouncer) return <Board {...props} />;
  return (
    <LiveAnnouncer>
      <Board {...props} />
    </LiveAnnouncer>
  );
}

export { KanbanBoard, moveKanbanCard, type KanbanBoardProps, type KanbanCard, type KanbanColumn, type KanbanMove } from './KanbanBoard';
export {
  useSortable,
  previewSortable,
  type UseSortableOptions,
  type UseSortableResult,
  type SortableContainer,
  type SortablePosition,
  type SortableMove,
  type SortableDrag,
  type SortableMode,
  type SortableEvents,
  type SortableItemProps,
  type SortableContainerProps,
} from './useSortable';
export { kanbanBoardVariants, type KanbanBoardVariantProps } from './kanban-board.variants';
export { doc as kanbanBoardDoc } from './KanbanBoard.doc';

import { tv, type VariantProps } from '../../utils/tv';

/**
 * Kanban board: columns on a muted surface, cards as raised tiles. The drop target column and
 * the dragged card take the brand border; nothing animates under reduced motion.
 */
export const kanbanBoardVariants = tv({
  slots: {
    root: 'flex w-full items-start gap-3 overflow-x-auto pb-2',
    column: [
      'flex w-72 shrink-0 flex-col rounded-xl border border-border bg-secondary/40',
      'transition-colors duration-150 motion-reduce:transition-none',
      'data-over:border-primary/60 data-over:bg-accent/40',
    ],
    header: 'flex items-center justify-between gap-2 px-3 pt-3 pb-2',
    heading: 'flex min-w-0 items-center gap-2 text-[13px] font-semibold text-foreground',
    title: 'truncate',
    count: 'rounded-full bg-secondary px-2 py-px font-mono text-[11px] font-medium tabular-nums text-muted-foreground',
    list: 'flex min-h-16 flex-col gap-2 px-2 pb-2',
    item: 'list-none',
    card: [
      'block w-full cursor-grab select-none rounded-lg border border-border bg-card text-start text-foreground shadow-sm',
      'transition-[box-shadow,border-color] duration-150 motion-reduce:transition-none',
      'hover:border-primary/40',
      'focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-focus-ring',
      'data-dragging:cursor-grabbing data-dragging:border-primary data-dragging:shadow-md',
    ],
    cardTitle: 'text-[13px] font-medium leading-5',
    cardDescription: 'mt-1 text-[12px] leading-5 text-muted-foreground',
    cardMeta: 'mt-2 flex flex-wrap items-center gap-2 font-mono text-[11px] text-muted-foreground',
    empty: 'list-none rounded-lg border border-dashed border-border px-3 py-4 text-center text-[12px] text-muted-foreground',
  },
  variants: {
    size: {
      auto: { card: 'px-control py-cell' },
      sm: { card: 'px-2.5 py-2' },
      md: { card: 'px-3.5 py-3' },
    },
  },
  defaultVariants: { size: 'auto' },
});

export type KanbanBoardVariantProps = VariantProps<typeof kanbanBoardVariants>;

import { useCallback, useEffect, useLayoutEffect, useMemo, useRef, useState, type KeyboardEvent, type PointerEvent as ReactPointerEvent } from 'react';
import { useI18n } from '../../i18n/I18nProvider';

/** A list of sortable items (a column, a lane, a single list). */
export interface SortableContainer {
  id: string;
  /** Item ids in order. */
  items: string[];
}

/** Where an item sits: container id and index (after removing the dragged item). */
export interface SortablePosition {
  containerId: string;
  index: number;
}

/** A completed move. `toIndex` is the index in the destination list once the item is removed from its origin. */
export interface SortableMove {
  itemId: string;
  fromContainerId: string;
  fromIndex: number;
  toContainerId: string;
  toIndex: number;
}

export type SortableMode = 'keyboard' | 'pointer';

export interface SortableDrag {
  itemId: string;
  mode: SortableMode;
  origin: SortablePosition;
  over: SortablePosition;
}

/** Lifecycle events, e.g. to announce them through a LiveAnnouncer. */
export interface SortableEvents {
  onDragStart?: (drag: SortableDrag) => void;
  onDragOver?: (drag: SortableDrag) => void;
  /** Fired on drop, whether or not the position changed (`onMove` only fires on a change). */
  onDragEnd?: (drag: SortableDrag) => void;
  onDragCancel?: (drag: SortableDrag) => void;
}

export interface UseSortableOptions extends SortableEvents {
  containers: SortableContainer[];
  /** Called once on drop when the item lands somewhere new. Apply it to your state (see `moveKanbanCard`). */
  onMove: (move: SortableMove) => void;
  disabled?: boolean;
  /** Pixels the pointer must travel before a drag starts (clicks below it stay clicks). Default 5. */
  activationDistance?: number;
  /** Touch press-and-hold delay in ms before a drag starts, so swipes still scroll. Default 250. */
  touchDelay?: number;
}

export interface SortableItemProps {
  ref: (el: HTMLElement | null) => () => void;
  onKeyDown: (event: KeyboardEvent<HTMLElement>) => void;
  onPointerDown: (event: ReactPointerEvent<HTMLElement>) => void;
  'aria-pressed': boolean;
  'data-sortable-item': string;
  'data-dragging'?: '';
}

export interface SortableContainerProps {
  ref: (el: HTMLElement | null) => () => void;
  'data-sortable-container': string;
  'data-over'?: '';
}

export interface UseSortableResult {
  /** The containers in preview order: render these (the dragged item already sits at its target). */
  containers: SortableContainer[];
  drag: SortableDrag | null;
  getItemProps: (itemId: string) => SortableItemProps;
  getContainerProps: (containerId: string) => SortableContainerProps;
  /** Cancels an in-progress drag (e.g. when the data changes underneath). */
  cancel: () => void;
}

function findPosition(containers: SortableContainer[], itemId: string): SortablePosition | null {
  for (const c of containers) {
    const index = c.items.indexOf(itemId);
    if (index >= 0) return { containerId: c.id, index };
  }
  return null;
}

/** Applies a drag to the containers: removes the item from its origin, inserts it at `over`. */
export function previewSortable(containers: SortableContainer[], drag: Pick<SortableDrag, 'itemId' | 'over'> | null): SortableContainer[] {
  if (!drag) return containers;
  const without = containers.map((c) => ({ id: c.id, items: c.items.filter((id) => id !== drag.itemId) }));
  return without.map((c) => {
    if (c.id !== drag.over.containerId) return c;
    const items = [...c.items];
    items.splice(Math.min(Math.max(drag.over.index, 0), items.length), 0, drag.itemId);
    return { id: c.id, items };
  });
}

const samePosition = (a: SortablePosition, b: SortablePosition) => a.containerId === b.containerId && a.index === b.index;

/**
 * Sortable lists with pointer and keyboard dragging, no dependencies. Space picks an item up,
 * arrows move it (↑↓ within a list, ←→ across lists, mirrored in RTL), Home/End jump to the
 * ends, Space or Enter drops, Escape (or Tab) cancels. Pointer drags start after a few pixels
 * (or a press-and-hold on touch). Controlled: the hook only previews; `onMove` commits.
 */
export function useSortable({
  containers,
  onMove,
  disabled = false,
  activationDistance = 5,
  touchDelay = 250,
  onDragStart,
  onDragOver,
  onDragEnd,
  onDragCancel,
}: UseSortableOptions): UseSortableResult {
  const { dir } = useI18n();
  const [drag, setDrag] = useState<SortableDrag | null>(null);
  const itemEls = useRef(new Map<string, HTMLElement>());
  const containerEls = useRef(new Map<string, HTMLElement>());
  const preview = useMemo(() => previewSortable(containers, drag), [containers, drag]);

  // Latest values for window listeners and stable callbacks.
  const latest = useRef({ containers, preview, drag, onMove, onDragStart, onDragOver, onDragEnd, onDragCancel });
  useLayoutEffect(() => {
    latest.current = { containers, preview, drag, onMove, onDragStart, onDragOver, onDragEnd, onDragCancel };
  });

  const start = useCallback((itemId: string, mode: SortableMode) => {
    const origin = findPosition(latest.current.containers, itemId);
    if (!origin) return null;
    const next: SortableDrag = { itemId, mode, origin, over: origin };
    latest.current.drag = next;
    setDrag(next);
    latest.current.onDragStart?.(next);
    return next;
  }, []);

  const moveTo = useCallback((over: SortablePosition) => {
    const current = latest.current.drag;
    if (!current || samePosition(current.over, over)) return;
    const next = { ...current, over };
    latest.current.drag = next;
    setDrag(next);
    latest.current.onDragOver?.(next);
  }, []);

  const drop = useCallback(() => {
    const current = latest.current.drag;
    if (!current) return;
    latest.current.drag = null;
    setDrag(null);
    if (!samePosition(current.origin, current.over)) {
      latest.current.onMove({
        itemId: current.itemId,
        fromContainerId: current.origin.containerId,
        fromIndex: current.origin.index,
        toContainerId: current.over.containerId,
        toIndex: current.over.index,
      });
    }
    latest.current.onDragEnd?.(current);
  }, []);

  const cancel = useCallback(() => {
    const current = latest.current.drag;
    if (!current) return;
    latest.current.drag = null;
    setDrag(null);
    latest.current.onDragCancel?.(current);
  }, []);

  // Keep keyboard focus on the dragged item when it re-mounts in another list, and after a drop.
  const focusTarget = drag?.mode === 'keyboard' ? drag.itemId : null;
  const lastKeyboardItem = useRef<string | null>(null);
  useLayoutEffect(() => {
    const id = focusTarget ?? lastKeyboardItem.current;
    lastKeyboardItem.current = focusTarget;
    if (!id) return;
    const el = itemEls.current.get(id);
    if (el && document.activeElement !== el && (focusTarget || !el.contains(document.activeElement))) el.focus({ preventScroll: false });
  });

  /** Position under the pointer: container by x (nearest if outside all), index by item midpoints. */
  const hitTest = useCallback((x: number, y: number, itemId: string): SortablePosition | null => {
    let best: { id: string; dist: number } | null = null;
    for (const [id, el] of containerEls.current) {
      const r = el.getBoundingClientRect();
      const dist = x < r.left ? r.left - x : x > r.right ? x - r.right : 0;
      if (!best || dist < best.dist) best = { id, dist };
    }
    if (!best) return null;
    const list = latest.current.preview.find((c) => c.id === best.id);
    if (!list) return null;
    let index = 0;
    for (const id of list.items) {
      if (id === itemId) continue;
      const el = itemEls.current.get(id);
      if (!el) continue;
      const r = el.getBoundingClientRect();
      if (r.top + r.height / 2 < y) index++;
    }
    return { containerId: best.id, index };
  }, []);

  const pointerCleanup = useRef<(() => void) | null>(null);
  useEffect(() => () => pointerCleanup.current?.(), []);

  const onPointerDown = useCallback(
    (itemId: string, event: ReactPointerEvent<HTMLElement>) => {
      if (disabled || event.button !== 0 || !event.isPrimary || latest.current.drag) return;
      const target = event.target as HTMLElement;
      if (target !== event.currentTarget && target.closest('a, button, input, select, textarea, [contenteditable="true"]')) return;
      pointerCleanup.current?.();
      const startX = event.clientX;
      const startY = event.clientY;
      const pointerId = event.pointerId;
      const touch = event.pointerType === 'touch';
      let active = false;
      let timer = 0;
      const begin = () => {
        if (active) return;
        active = !!start(itemId, 'pointer');
      };
      if (touch) timer = window.setTimeout(begin, touchDelay);
      const move = (e: PointerEvent) => {
        if (e.pointerId !== pointerId) return;
        if (!active) {
          const far = Math.hypot(e.clientX - startX, e.clientY - startY) >= activationDistance;
          if (touch) {
            if (far) cleanup();
            return;
          }
          if (!far) return;
          begin();
        }
        const over = hitTest(e.clientX, e.clientY, itemId);
        if (over) moveTo(over);
      };
      const up = (e: PointerEvent) => {
        if (e.pointerId !== pointerId) return;
        if (active) {
          // Swallow the click that follows a drag.
          const swallow = (c: MouseEvent) => {
            c.stopPropagation();
            c.preventDefault();
          };
          window.addEventListener('click', swallow, { capture: true, once: true });
          window.setTimeout(() => window.removeEventListener('click', swallow, true), 0);
          drop();
        }
        cleanup();
      };
      const cancelPointer = () => {
        if (active) cancel();
        cleanup();
      };
      const key = (e: globalThis.KeyboardEvent) => {
        if (e.key === 'Escape' && active) {
          e.preventDefault();
          cancelPointer();
        }
      };
      const touchMove = (e: TouchEvent) => {
        if (active) e.preventDefault();
      };
      function cleanup() {
        window.clearTimeout(timer);
        window.removeEventListener('pointermove', move);
        window.removeEventListener('pointerup', up);
        window.removeEventListener('pointercancel', cancelPointer);
        window.removeEventListener('keydown', key, true);
        window.removeEventListener('touchmove', touchMove);
        pointerCleanup.current = null;
      }
      window.addEventListener('pointermove', move);
      window.addEventListener('pointerup', up);
      window.addEventListener('pointercancel', cancelPointer);
      window.addEventListener('keydown', key, true);
      window.addEventListener('touchmove', touchMove, { passive: false });
      pointerCleanup.current = cleanup;
    },
    [disabled, start, hitTest, moveTo, drop, cancel, activationDistance, touchDelay],
  );

  const onKeyDown = useCallback(
    (itemId: string, event: KeyboardEvent<HTMLElement>) => {
      if (disabled || event.target !== event.currentTarget) return;
      const current = latest.current.drag;
      if (!current) {
        if (event.key === ' ') {
          event.preventDefault();
          start(itemId, 'keyboard');
        }
        return;
      }
      if (current.itemId !== itemId || current.mode !== 'keyboard') return;
      const lists = latest.current.preview;
      const ci = lists.findIndex((c) => c.id === current.over.containerId);
      const lengthOf = (i: number) => (lists[i]?.items.filter((id) => id !== itemId).length ?? 0);
      const across = (step: number) => {
        const ni = Math.min(Math.max(ci + step, 0), lists.length - 1);
        const next = lists[ni];
        if (next) moveTo({ containerId: next.id, index: Math.min(current.over.index, lengthOf(ni)) });
      };
      const rtl = dir === 'rtl';
      switch (event.key) {
        case ' ':
        case 'Enter':
          event.preventDefault();
          drop();
          return;
        case 'Escape':
          event.preventDefault();
          cancel();
          return;
        case 'Tab':
          cancel();
          return;
        case 'ArrowUp':
          event.preventDefault();
          moveTo({ ...current.over, index: Math.max(current.over.index - 1, 0) });
          return;
        case 'ArrowDown':
          event.preventDefault();
          moveTo({ ...current.over, index: Math.min(current.over.index + 1, lengthOf(ci)) });
          return;
        case 'ArrowLeft':
          event.preventDefault();
          across(rtl ? 1 : -1);
          return;
        case 'ArrowRight':
          event.preventDefault();
          across(rtl ? -1 : 1);
          return;
        case 'Home':
          event.preventDefault();
          moveTo({ ...current.over, index: 0 });
          return;
        case 'End':
          event.preventDefault();
          moveTo({ ...current.over, index: lengthOf(ci) });
          return;
        default:
      }
    },
    [disabled, dir, start, moveTo, drop, cancel],
  );

  const getItemProps = useCallback(
    (itemId: string): SortableItemProps => ({
      ref: (el) => {
        if (el) itemEls.current.set(itemId, el);
        return () => {
          if (el && itemEls.current.get(itemId) === el) itemEls.current.delete(itemId);
        };
      },
      onKeyDown: (e) => onKeyDown(itemId, e),
      onPointerDown: (e) => onPointerDown(itemId, e),
      'aria-pressed': drag?.itemId === itemId,
      'data-sortable-item': itemId,
      'data-dragging': drag?.itemId === itemId ? '' : undefined,
    }),
    [drag, onKeyDown, onPointerDown],
  );

  const getContainerProps = useCallback(
    (containerId: string): SortableContainerProps => ({
      ref: (el) => {
        if (el) containerEls.current.set(containerId, el);
        return () => {
          if (el && containerEls.current.get(containerId) === el) containerEls.current.delete(containerId);
        };
      },
      'data-sortable-container': containerId,
      'data-over': drag && drag.over.containerId === containerId ? '' : undefined,
    }),
    [drag],
  );

  return { containers: preview, drag, getItemProps, getContainerProps, cancel };
}

import { DirectionProvider } from '@base-ui/react/direction-provider';
import { createContext, useContext, useEffect, useMemo, type ReactNode } from 'react';
import { createFormatters, localeDirection, type I18nFormatters } from './format';
import { catalogs } from './messages';
import { en, type Messages } from './messages/en';

export type Direction = 'ltr' | 'rtl';

/** What useI18n() returns: the translator, Intl formatters, the locale and the text direction. */
export interface I18n extends I18nFormatters {
  locale: string;
  dir: Direction;
}

export interface I18nProviderProps {
  /** BCP 47 locale ("es", "es-MX", "ar"). Picks the built-in catalog by language; unknown → English. */
  locale: string;
  /** Overrides or additions on top of the built-in catalog (e.g. a full catalog for another language). */
  messages?: Partial<Messages>;
  /** Text direction; defaults to the locale's (rtl for Arabic, Hebrew, Persian, Urdu…). */
  dir?: Direction;
  /**
   * Where `dir` and `lang` are applied: `wrapper` (default) renders a `display: contents` div;
   * `document` sets them on `<html>` (also covers portalled overlays); `none` leaves it to you.
   */
  applyTo?: 'wrapper' | 'document' | 'none';
  children?: ReactNode;
}

const I18nContext = createContext<I18n | null>(null);
const DEFAULT_I18N: I18n = { locale: 'en', dir: 'ltr', ...createFormatters('en', en) };

/** The built-in catalog for a locale's language, falling back to English. */
export function builtInMessages(locale: string): Messages {
  const lang = locale.split(/[-_]/)[0]?.toLowerCase() ?? '';
  return (catalogs as Record<string, Messages | undefined>)[lang] ?? en;
}

/**
 * Locale, messages and direction for every kit component below it. Also sets Base UI's
 * direction, so arrow-key navigation (Tabs, Menu, Slider, Toolbar…) follows RTL.
 */
export function I18nProvider({ locale, messages, dir, applyTo = 'wrapper', children }: I18nProviderProps) {
  const direction = dir ?? localeDirection(locale);
  const value = useMemo<I18n>(() => {
    const merged: Messages = { ...builtInMessages(locale), ...messages };
    return { locale, dir: direction, ...createFormatters(locale, merged) };
  }, [locale, messages, direction]);

  useEffect(() => {
    if (applyTo !== 'document') return;
    const html = document.documentElement;
    const prev = { dir: html.getAttribute('dir'), lang: html.getAttribute('lang') };
    html.setAttribute('dir', direction);
    html.setAttribute('lang', locale);
    return () => {
      if (prev.dir === null) html.removeAttribute('dir');
      else html.setAttribute('dir', prev.dir);
      if (prev.lang === null) html.removeAttribute('lang');
      else html.setAttribute('lang', prev.lang);
    };
  }, [applyTo, direction, locale]);

  const content = <DirectionProvider direction={direction}>{children}</DirectionProvider>;
  return (
    <I18nContext.Provider value={value}>
      {applyTo === 'wrapper' ? (
        <div dir={direction} lang={locale} className="contents">
          {content}
        </div>
      ) : (
        content
      )}
    </I18nContext.Provider>
  );
}

/** Translator, Intl formatters, locale and direction. Outside an I18nProvider: English, LTR. */
export function useI18n(): I18n {
  return useContext(I18nContext) ?? DEFAULT_I18N;
}

/** The provider's value, or null outside one (lets components keep runtime-locale defaults). */
export function useOptionalI18n(): I18n | null {
  return useContext(I18nContext);
}

/**
 * `dir` for portalled overlays: rendered outside the provider's wrapper, they carry the
 * direction themselves. Undefined outside a provider, so the document's direction applies.
 */
export function usePortalDir(): Direction | undefined {
  return useContext(I18nContext)?.dir;
}

import type { MessageKey, Messages } from './messages/en';

/** Values interpolated into a message: `{name}` placeholders and plural selectors. */
export type MessageVars = Record<string, string | number>;

/** Scripts written right to left (language subtag). */
const RTL_LANGUAGES = new Set(['ar', 'arc', 'ckb', 'dv', 'fa', 'he', 'iw', 'ks', 'ku', 'ps', 'sd', 'ug', 'ur', 'yi']);

/** `rtl` for Arabic, Hebrew, Persian, Urdu… (by language subtag or Intl text info), else `ltr`. */
export function localeDirection(locale: string): 'ltr' | 'rtl' {
  try {
    const loc = new Intl.Locale(locale) as Intl.Locale & {
      getTextInfo?: () => { direction?: string };
      textInfo?: { direction?: string };
    };
    const info = loc.getTextInfo?.() ?? loc.textInfo;
    if (info?.direction === 'rtl' || info?.direction === 'ltr') return info.direction;
    return RTL_LANGUAGES.has(loc.language) ? 'rtl' : 'ltr';
  } catch {
    return RTL_LANGUAGES.has(locale.split(/[-_]/)[0]?.toLowerCase() ?? '') ? 'rtl' : 'ltr';
  }
}

/** Index of the brace closing the one at `open` (nested braces allowed). */
function matchBrace(text: string, open: number): number {
  let depth = 0;
  for (let i = open; i < text.length; i++) {
    if (text[i] === '{') depth++;
    else if (text[i] === '}' && --depth === 0) return i;
  }
  return -1;
}

/** `one {# item} other {# items}` → `{ one: '# item', other: '# items' }`. */
function parseBranches(body: string): Record<string, string> {
  const branches: Record<string, string> = {};
  let i = 0;
  while (i < body.length) {
    const open = body.indexOf('{', i);
    if (open < 0) break;
    const name = body.slice(i, open).trim();
    const close = matchBrace(body, open);
    if (close < 0) break;
    branches[name] = body.slice(open + 1, close);
    i = close + 1;
  }
  return branches;
}

/** Fills `{name}` placeholders and `{count, plural, one {…} other {…}}` selectors. */
export function interpolate(template: string, vars: MessageVars | undefined, locale: string): string {
  if (!vars || !template.includes('{')) return template;
  let out = '';
  let i = 0;
  while (i < template.length) {
    const open = template.indexOf('{', i);
    if (open < 0) {
      out += template.slice(i);
      break;
    }
    out += template.slice(i, open);
    const close = matchBrace(template, open);
    if (close < 0) {
      out += template.slice(open);
      break;
    }
    const inner = template.slice(open + 1, close);
    const plural = /^\s*(\w+)\s*,\s*plural\s*,(.*)$/s.exec(inner);
    if (plural) {
      const name = plural[1] ?? '';
      const n = Number(vars[name] ?? 0);
      const branches = parseBranches(plural[2] ?? '');
      const rule = new Intl.PluralRules(locale).select(n);
      const branch = branches[`=${n}`] ?? branches[rule] ?? branches.other ?? '';
      out += interpolate(branch.replaceAll('#', new Intl.NumberFormat(locale).format(n)), vars, locale);
    } else {
      const value = vars[inner.trim()];
      out += value === undefined ? `{${inner}}` : String(value);
    }
    i = close + 1;
  }
  return out;
}

export type DateValue = Date | number | string;
const toDate = (value: DateValue) => (value instanceof Date ? value : new Date(value));

const RELATIVE_UNITS: [Intl.RelativeTimeFormatUnit, number][] = [
  ['year', 365 * 24 * 3600],
  ['month', 30 * 24 * 3600],
  ['week', 7 * 24 * 3600],
  ['day', 24 * 3600],
  ['hour', 3600],
  ['minute', 60],
  ['second', 1],
];

/** The translator and Intl formatters for one locale. */
export interface I18nFormatters {
  /** Translates a built-in key, filling placeholders. */
  t: (key: MessageKey, vars?: MessageVars) => string;
  formatNumber: (value: number, options?: Intl.NumberFormatOptions) => string;
  formatCurrency: (value: number, currency: string, options?: Intl.NumberFormatOptions) => string;
  formatDate: (value: DateValue, options?: Intl.DateTimeFormatOptions) => string;
  /**
   * Relative time. With a unit, formats `value` in it ("in 3 days"); with a date, picks the
   * largest fitting unit against `now` ("5 minutes ago").
   */
  formatRelativeTime: {
    (value: number, unit: Intl.RelativeTimeFormatUnit, options?: Intl.RelativeTimeFormatOptions): string;
    (value: Date, now?: Date | number, options?: Intl.RelativeTimeFormatOptions): string;
  };
  formatList: (items: readonly string[], options?: Intl.ListFormatOptions) => string;
}

export function createFormatters(locale: string, messages: Messages): I18nFormatters {
  function formatRelativeTime(value: number, unit: Intl.RelativeTimeFormatUnit, options?: Intl.RelativeTimeFormatOptions): string;
  function formatRelativeTime(value: Date, now?: Date | number, options?: Intl.RelativeTimeFormatOptions): string;
  function formatRelativeTime(
    value: number | Date,
    unitOrNow?: Intl.RelativeTimeFormatUnit | Date | number,
    options: Intl.RelativeTimeFormatOptions = { numeric: 'auto' },
  ): string {
    const rtf = new Intl.RelativeTimeFormat(locale, options);
    if (typeof value === 'number' && typeof unitOrNow === 'string') return rtf.format(value, unitOrNow);
    const now = unitOrNow instanceof Date ? unitOrNow.getTime() : typeof unitOrNow === 'number' ? unitOrNow : Date.now();
    const seconds = Math.round((toDate(value).getTime() - now) / 1000);
    const [unit, size] = RELATIVE_UNITS.find(([, s]) => Math.abs(seconds) >= s) ?? ['second', 1];
    return rtf.format(Math.round(seconds / size), unit);
  }
  return {
    t: (key, vars) => interpolate(messages[key] ?? key, vars, locale),
    formatNumber: (value, options) => new Intl.NumberFormat(locale, options).format(value),
    formatCurrency: (value, currency, options) => new Intl.NumberFormat(locale, { style: 'currency', currency, ...options }).format(value),
    formatDate: (value, options = { dateStyle: 'medium' }) => new Intl.DateTimeFormat(locale, options).format(toDate(value)),
    formatRelativeTime,
    formatList: (items, options = { style: 'long', type: 'conjunction' }) => new Intl.ListFormat(locale, options).format(items),
  };
}

import { en, type Messages } from './en';
import { es } from './es';

/** Built-in catalogs, by language subtag. */
export const catalogs = { en, es } satisfies Record<string, Messages>;
export type CatalogLocale = keyof typeof catalogs;

/**
 * Component documentation contract. Every component folder exports a `*.doc.ts`
 * with this shape; the registry build and the docs site read it.
 */
export interface ComponentDoc {
  /** Public component name, e.g. "Button". */
  name: string;
  /** Inventory group, e.g. "Actions", "Forms", "Overlays". */
  group: 'Actions' | 'Forms' | 'Overlays' | 'Navigation' | 'Display' | 'Feedback' | 'Layout' | 'Theme';
  /** Lifecycle badge. */
  status: 'stable' | 'beta' | 'experimental';
  description: string;
  /** Headless primitive it is built on, if any (e.g. "@base-ui/react/dialog"). */
  primitive?: string;
  /** WAI-ARIA pattern the a11y contract test checks. */
  pattern?: string;
  /** Keyboard contract: key → behaviour. Each row is covered by a test. */
  keyboard?: Array<[key: string, behaviour: string]>;
  /** Tokens the component reads (for the theming docs). */
  tokens?: string[];
}
